from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        adj = [[] for _ in range(n)]

        # Build adjacency list
        for i in range(n):
            for j in range(i + 1, n):
                # Count common elements between properties[i] and properties[j]
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Count connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                visited[i] = True
                self.bfs(adj, i, visited)

        return components

    def bfs(self, adj, start, visited):
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
