        total_sum = 0

        for i in range(n):
            # Check if i-k and i+k exist
            left_exists = i - k >= 0
            right_exists = i + k < n

            # Check if strictly greater than both neighbors
            if left_exists and right_exists:
                if nums[i] > nums[i - k] and nums[i] > nums[i + k]:
                    total_sum += nums[i]
            elif left_exists:
                if nums[i] > nums[i - k]:
                    total_sum += nums[i]
            elif right_exists:
                if nums[i] > nums[i + k]:
                    total_sum += nums[i]
            # If neither exists, it's still good

