class Solution:
    def findValidPair(self, s: str) -> str:
        # Count occurrences of each digit
        counts = {}
        for digit in s:
            counts[digit] = counts.get(digit, 0) + 1

        # Traverse the string to find valid adjacent pairs
        for i in range(len(s) - 1):
            d1 = s[i]
            d2 = s[i+1]

            # Check if digits are different
            if d1 == d2:
                continue

            # Check if counts match the digit values
            if counts[d1] == int(d1) and counts[d2] == int(d2):
                return d1 + d2

        return ""
